using UnityEditor;
using UnityEngine;

public static class ResizePrototypeGround
{
    public static string Main()
    {
        var ground = GameObject.Find("Prototype_Test_Area/TestGround");
        if (ground == null) return "Base do protótipo não encontrada.";
        ground.transform.localScale = new Vector3(0.35f, 1f, 0.35f);
        EditorUtility.SetDirty(ground);
        return "Base do protótipo ajustada para 35% do tamanho original.";
    }
}
